-- PT115-S4-Q3. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT115-S4-Q3$batch06$ AND q.stimulus=$batch06$Tom: Critics of recent high court decisions claim that judges’ willingness to abide by earlier decisions is necessary to avoid legal chaos. Since high courts of the past often repudiated legal precedents and no harm to the legal system ensued, these critics’ objections must be politically motivated and ought to be ignored.
Mary: High courts have repudiated precedents in the past, but they were careful to do so only when the previous rulings were old and had clearly become outdated. The recently overturned rulings were themselves recent. Overturning any recent legal ruling diminishes the law, which comes to be viewed as unstable and capricious.$batch06$ AND q.prompt=$batch06$Mary responds to Tom's argument in which one of the following ways?$batch06$ AND q.correct_choice=$batch06$E$batch06$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT115-S4-Q3$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT115-S4-Q3$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Mary, implied) Overturning these recent rulings does harm, so the critics have a point.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$Past courts overturned only old, clearly outdated rulings. The rulings recently overturned were themselves recent, and overturning recent rulings makes the law look unstable.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Tom's evidence is that courts often overturned precedent in the past with no harm. Mary accepts that, then splits the cases in two: old, outdated rulings versus recent ones. Tom's history only covers the first kind. The recent decisions are the second kind, so his evidence does not reach them.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Drawing a distinction Tom missed between two kinds of overturned precedent.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT115-S4-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Mary does not dispute that past reversals caused no harm.$batch06$), ($batch06$B$batch06$, $batch06$Mary never agrees with Tom about the critics' motives.$batch06$), ($batch06$C$batch06$, $batch06$This is the most popular wrong answer. Mary does say past courts were careful, which sounds like a defense. But she is not defending overturning precedent. She is *criticizing* the recent overturning, and uses the past care to show how the recent decisions are different.$batch06$), ($batch06$D$batch06$, $batch06$Mary does not show that Tom's own evidence contradicts his assumption.$batch06$), ($batch06$E$batch06$, $batch06$The two kinds are old, outdated precedents and recent ones. The difference Tom ignores is that only the recent kind makes the law look unstable.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT115-S4-Q3$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
